// <summary>
// Transaction classifier - identifies which of the 13 reconciliation rules applies.
// Chain-of-responsibility, priority ordered (most specific rule wins).
// </summary>
public class PremBankRecHelper
{
    private static const str KEYWORD_TERMINAL       = 'TERMINAL';
    private static const str KEYWORD_CARDS_SETTL    = 'CARDS SETTL';
    private static const str KEYWORD_PREMMOTORS     = 'PREMMOTORSPRIVATELIMITED';
    private static const str KEYWORD_INSURANCE      = 'INSURANCE';
    private static const str KEYWORD_SETTL_CHRG     = 'SETTLEMENT CHARGES';
    private static const str KEYWORD_MSF            = 'MSF';
    private static const str KEYWORD_NEFT_RETURN    = 'NEFT RETURN';
    private static const str KEYWORD_NEFT_RET       = 'NEFT RET';
    private static const str KEYWORD_CHQ_DEP_RET    = 'CHQ DEP RET';
    private static const str KEYWORD_ADVICE_NOT     = 'ADVICE NOT RECEIVED';
    private static const str KEYWORD_CASH_DEPOSIT   = 'CASH DEPOSIT';
    private static const str KEYWORD_CASH_DEP       = 'CASH DEP';
    private static const str KEYWORD_CHQ_DEP        = 'CHQ DEP';
    private static const str KEYWORD_CTS_CLG        = 'CTS CLG';
    private static const str KEYWORD_CHQ_PAID       = 'CHQ PAID';
    private static const str KEYWORD_NEFT_CR        = 'NEFT CR';
    private static const str KEYWORD_RTGS_CR        = 'RTGS CR';
    private static const str KEYWORD_IMPS           = 'IMPS-';
    private static const str KEYWORD_NEFT           = 'NEFT';
    private static const str KEYWORD_RTGS_DR        = 'RTGS DR';

}

